#include <iostream>

using namespace std;

class Vector2D {
private:
    double x, y; // Thuộc tính tọa độ x và y

public:
    // Cấu tử mặc định (hỗ trợ khởi tạo không tham số hoặc có tham số)
    Vector2D(double x_val = 0.0, double y_val = 0.0) : x(x_val), y(y_val) {}

    // Nạp chồng toán tử * (Tính tích vô hướng: x1*x2 + y1*y2)
    double operator*(const Vector2D& other) const {
        return (this->x * other.x) + (this->y * other.y);
    }

    // Nạp chồng toán tử +=
    Vector2D& operator+=(const Vector2D& other) {
        this->x += other.x;
        this->y += other.y;
        return *this;
    }

    // Nạp chồng toán tử !=
    bool operator!=(const Vector2D& other) const {
        return (this->x != other.x) || (this->y != other.y);
    }

    // Hàm bạn toán tử nhập >>
    friend istream& operator>>(istream& in, Vector2D& v) {
        cout << "Nhap hoanh do x: ";
        in >> v.x;
        cout << "Nhap tung do y: ";
        in >> v.y;
        return in;
    }

    // Hàm bạn toán tử xuất <<
    friend ostream& operator<<(ostream& out, const Vector2D& v) {
        out << "(" << v.x << ", " << v.y << ")";
        return out;
    }
};

int main() {
    Vector2D v1, v2;

    // Nhập dữ liệu cho 2 vector
    cout << "--- Nhap vector v1 ---" << endl;
    cin >> v1;
    cout << "\n--- Nhap vector v2 ---" << endl;
    cin >> v2;

    // In thông tin 2 vector vừa nhập
    cout << "\nVector v1: " << v1 << endl;
    cout << "Vector v2: " << v2 << endl;

    // Tính và in tích vô hướng v1 * v2
    double tich_vo_huong = v1 * v2;
    cout << "\nTich vo huong v1 * v2 = " << tich_vo_huong << endl;

    // Kiểm tra toán tử != (ví dụ thêm để chứng minh hoạt động)
    if (v1 != v2) {
        cout << "Hai vector v1 va v2 khac nhau." << endl;
    } else {
        cout << "Hai vector v1 va v2 bang nhau." << endl;
    }

    // Thực hiện v1 += v2 và in v1
    v1 += v2;
    cout << "\nSau khi thuc hien v1 += v2:" << endl;
    cout << "Vector v1 moi = " << v1 << endl;

    return 0;
}

